begin;set local lock_timeout='3s';set local statement_timeout='10s';do $g$ declare a jsonb;begin select to_jsonb(e) into a from public.editions e where id=978200999 for update;if a is distinct from '{"id":978200999,"work_id":978100123,"title":"TEST PR68 dependency only","language":null,"isbn_10":null,"isbn_13":null,"publisher":null,"cover_id":null,"publish_date":null,"open_library_edition_id":null}'::jsonb then raise exception 'Later test fixture change';end if;if exists(select 1 from public.catalog_edition_metadata where edition_id=978200999) then raise exception 'Unexpected new metadata';end if;delete from public.editions where id=978200999;end;$g$;select jsonb_build_object('case','dependency-cleaned','remaining',(select count(*) from public.editions where id=978200999)) as result;commit;
